    p: "dark_oak_planks",
    f: "dark_oak_fence",
    t: ["dark_oak_slab", { type: "bottom" }],
    w: ["dark_oak_stairs", { facing: "west", half: "bottom" }],
    e: ["dark_oak_stairs", { facing: "east", half: "bottom" }],
  };
  // chests face north or south; the south ones face north (into the room), the east-wall ones face west
  const eastChests = [[38, 6], [38, 7]];
  layers(g, [X0, 19, Z0], legend, [text(floor), text(top)]);
